/* Generated from themes/stadium.json. Do not edit; run pnpm tokens:build.
   The stadium theme on its own, for a consumer installing @gamestage/theme-stadium.
   Needs gamestage-tokens.css for the values it does not override, and its own
   font item for the families it names. */

@layer gs.base, gs.context, gs.theme;

@layer gs.theme {
  [data-gs-theme="stadium"] {
  --gs-depth-style: glow;
  --gs-press-transform: none;
  --gs-color-background: oklch(0.15 0.035 240);
  --gs-color-background-solid: oklch(0.15 0.035 240);
  --gs-color-surface: oklch(0.20 0.04 238);
  --gs-color-surface-solid: oklch(0.20 0.04 238);
  --gs-color-surface-raised: oklch(0.26 0.045 236);
  --gs-color-surface-raised-solid: oklch(0.26 0.045 236);
  --gs-color-edge: oklch(0.34 0.05 235);
  --gs-color-edge-solid: oklch(0.34 0.05 235);
  --gs-color-edge-high: oklch(0.68 0.09 95);
  --gs-color-edge-high-solid: oklch(0.68 0.09 95);
  --gs-color-ink: #ffffff;
  --gs-color-ink-solid: #ffffff;
  --gs-color-ink-secondary: oklch(0.83 0.02 235);
  --gs-color-ink-secondary-solid: oklch(0.83 0.02 235);
  --gs-color-muted: oklch(0.60 0.025 235);
  --gs-color-muted-solid: oklch(0.60 0.025 235);
  --gs-color-interactive: oklch(0.76 0.14 85);
  --gs-color-interactive-solid: oklch(0.76 0.14 85);
  --gs-color-interactive-hover: oklch(0.82 0.14 85);
  --gs-color-interactive-hover-solid: oklch(0.82 0.14 85);
  --gs-color-interactive-base: oklch(0.52 0.12 80);
  --gs-color-interactive-base-solid: oklch(0.52 0.12 80);
  --gs-color-selected: oklch(0.78 0.13 200);
  --gs-color-selected-solid: oklch(0.78 0.13 200);
  --gs-color-positive: oklch(0.74 0.17 145);
  --gs-color-positive-solid: oklch(0.74 0.17 145);
  --gs-color-positive-base: oklch(0.50 0.14 145);
  --gs-color-positive-base-solid: oklch(0.50 0.14 145);
  --gs-color-negative: oklch(0.66 0.20 25);
  --gs-color-negative-solid: oklch(0.66 0.20 25);
  --gs-color-negative-base: oklch(0.44 0.17 25);
  --gs-color-negative-base-solid: oklch(0.44 0.17 25);
  --gs-color-warning: oklch(0.80 0.15 65);
  --gs-color-warning-solid: oklch(0.80 0.15 65);
  --gs-color-reward: oklch(0.88 0.14 95);
  --gs-color-reward-solid: oklch(0.88 0.14 95);
  --gs-color-reward-base: oklch(0.64 0.13 90);
  --gs-color-reward-base-solid: oklch(0.64 0.13 90);
  --gs-color-player: oklch(0.72 0.15 230);
  --gs-color-player-solid: oklch(0.72 0.15 230);
  --gs-color-opponent: oklch(0.70 0.19 340);
  --gs-color-opponent-solid: oklch(0.70 0.19 340);
  --gs-color-disabled: oklch(0.36 0.03 236);
  --gs-color-disabled-solid: oklch(0.36 0.03 236);
  --gs-color-disabled-ink: oklch(0.58 0.02 235);
  --gs-color-disabled-ink-solid: oklch(0.58 0.02 235);
  --gs-color-on-accent: oklch(0.16 0.03 240);
  --gs-color-on-accent-solid: oklch(0.16 0.03 240);
  --gs-color-on-bright: oklch(0.16 0.03 240);
  --gs-color-on-bright-solid: oklch(0.16 0.03 240);
  --gs-color-scrim: rgba(6,10,24,0.6);
  --gs-color-scrim-solid: rgba(6,10,24,0.6);
  --gs-depth-styles-offset-pressable: inset 0 1px 0 rgba(255,255,255,.3), 0 var(--gs-press-travel) 0 var(--gs-color-interactive-base);
  --gs-depth-styles-squeeze-pressable: 0 0 0 var(--gs-stroke-control) var(--gs-color-edge);
  --gs-depth-styles-squeeze-pressed: 0 0 0 var(--gs-stroke-selected) var(--gs-color-interactive-solid);
  --gs-depth-styles-glow-pressable: 0 0 0 var(--gs-stroke-control) var(--gs-color-edge-high);
  --gs-depth-styles-glow-pressed: 0 0 0 var(--gs-stroke-selected) var(--gs-color-interactive-solid);
  --gs-depth-raised: 0 5px 0 var(--gs-color-edge);
  --gs-depth-pressable: inset 0 1px 0 rgba(255,255,255,.3), 0 var(--gs-press-travel) 0 var(--gs-color-interactive-base);
  --gs-depth-reward: 0 0 0 3px var(--gs-color-background-solid), 0 0 0 5px var(--gs-color-reward-solid), 0 0 28px oklch(0.87 0.17 92 / .45);
  --gs-depth-pressable-positive: inset 0 1px 0 rgba(255,255,255,.35), 0 var(--gs-press-travel) 0 var(--gs-color-positive-base);
  }
}
